CREATE VIEW "EXT"."CSA_BAL_RDC_RESUMEN_SVW" ( "TIPO_INFORME", "PERIODO_FILTRO", "PERIODO_FORMATO", "PERIODO_TABLA", "COD_AGENTE", "NOMBRE_AGENTE", "NIF", "NIF_NOMBRE", "TIPO_AGENTE", "POL_FIS_REC", "POL_CORR_REC", "PRIMA_CORR", "IMPORTE_PAGO", "BALANCES_MESES_ANT", "IMPORTE_TOTAL_PAGADO", "OBJ_REG_CUAT", "COMP_CUAT_RAPPEL", "IGUALES", "SOLO_DIFERENCIAS", "FEC_ACTUALIZACION", "POSITIONSEQ", "PERIODSEQ" ) AS (SELECT "TIPO_INFORME" , "PERIODO_FILTRO" , "PERIODO_FORMATO" , "PERIODO_TABLA" , "COD_AGENTE" , "NOMBRE_AGENTE" , "NIF" , "NIF_NOMBRE" , "TIPO_AGENTE" , "POL_FIS_REC" , "POL_CORR_REC" , "PRIMA_CORR" , "IMPORTE_PAGO" , "BALANCES_MESES_ANT" , "IMPORTE_TOTAL_PAGADO" , "OBJ_REG_CUAT" , "COMP_CUAT_RAPPEL" , "IGUALES" , "SOLO_DIFERENCIAS" , "FEC_ACTUALIZACION" , "POSITIONSEQ" , "PERIODSEQ" FROM EXT.OUT_RDC_RESUMEN_FINAL_REP
	WHERE TIPO_INFORME = 'BAL'
		AND PERIODSEQ IN (SELECT PERIODSEQ FROM EXT.LIB_CREAR_TABLAS:N_MESES(13)))